import AjvModule from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  validator?: ValidateFunction;
  execute: ToolExecutor;
}

interface SchemaIssue {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: Record<string, unknown>;
}

interface ValidateFunction {
  (data: unknown): boolean;
  errors?: SchemaIssue[] | null;
}

interface SchemaCompiler {
  compile(schema: Record<string, unknown>): ValidateFunction;
}

type SchemaCompilerConstructor = new (options: Record<string, unknown>) => SchemaCompiler;

const AjvExports = AjvModule as unknown as SchemaCompilerConstructor | {default: SchemaCompilerConstructor};
const Ajv = 'default' in AjvExports ? AjvExports.default : AjvExports;

const ISSUE_DESCRIBERS: Record<string, (issue: SchemaIssue) => string> = {
  required: issue => `missing required property '${String(issue.params.missingProperty)}'`,
  type: issue => `must be of type ${String(issue.params.type)}`,
  enum: issue => `must be one of ${JSON.stringify(issue.params.allowedValues)}`,
};

function describeError(issue: SchemaIssue): string {
  const describe = ISSUE_DESCRIBERS[issue.keyword] ?? (() => `failed '${issue.keyword}' constraint`);
  return `${issuePath(issue) || '(root)'}: ${describe(issue)}`;
}

// Ajv 8 reports `instancePath` ('/a/b'); Ajv 6 reports `dataPath` ('.a.b'). Name the path either way.
function issuePath(issue: SchemaIssue): string {
  return issue.instancePath ?? (issue.dataPath ?? '').replace(/\.([^.[\]]+)/g, '/$1');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${(error as Error).message}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, validator, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private validatorFor(tool: StoredTool, schema: Record<string, unknown>): ValidateFunction {
    if (tool.validator) return tool.validator;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const compiled = this.ajv.compile(schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }

  /** Validates input against the tool's inputSchema; contract in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const validate = this.validatorFor(tool, this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) {
      const problems = (validate.errors ?? []).map(describeError);
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for tool ${name}: ${problems.join('; ')}`};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects a value outside the declared enum without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'set_unit',
        description: 'Set unit',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('set_unit', {unit: 'kelvin'});

    expect({
      executorCalls,
      namesPath: response.result.includes('/unit'),
      namesAllowed: response.result.includes('celsius'),
      leaksValue: response.result.includes('kelvin'),
    }).toEqual({executorCalls: 0, namesPath: true, namesAllowed: true, leaksValue: false});
  });

  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, units: {type: 'string', default: 'celsius'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Paris', extra: 1});

    expect(received).toEqual([{location: 'Paris', extra: 1}]);
  });

  it('validates a function-valued definition against the schema current at each call', async () => {
    const registry = new ToolRegistry();
    let required = 'city';
    const received: Record<string, unknown>[] = [];
    registry.register(
      () => ({
        name: 'lookup',
        description: 'Lookup',
        inputSchema: {type: 'object', properties: {[required]: {type: 'string'}}, required: [required]},
      }),
      async input => {
        received.push(input);
        return 'ok';
      }
    );

    const first = await registry.execute('lookup', {city: 'Paris'});
    required = 'zip';
    const second = await registry.execute('lookup', {city: 'Paris'});

    expect({
      received,
      firstRejected: first.result.includes('Invalid'),
      secondNamesZip: second.result.includes('zip'),
    }).toEqual({
      received: [{city: 'Paris'}],
      firstRejected: false,
      secondNamesZip: true,
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
